package codegen

// migrationTemplate puts the tenant boundary into the table itself. A generated
// module cannot forget it: tenant_id, the insert trigger and FORCE RLS are part
// of the template, not a follow-up step.
const migrationTemplate = `-- {{.Spec.Title}} ({{.Spec.Table}})
--
-- Generated by cmd/gen-module. The tenant boundary is part of the table:
--   * tenant_id is NOT NULL, so a row without a tenant cannot exist;
--   * the insert trigger takes the tenant from the session and raises when
--     there is none, instead of silently defaulting to tenant 1;
--   * FORCE ROW LEVEL SECURITY applies to the table owner too, so the only way
--     to cross tenants is the platform identity.
-- Re-runnable: the deploy path applies migrations with a plain psql loop.

CREATE TABLE IF NOT EXISTS {{.Spec.Table}} (
  id BIGSERIAL,
  tenant_id BIGINT NOT NULL DEFAULT 1,
{{.Columns}}  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  deleted_at TIMESTAMPTZ NULL,
  PRIMARY KEY (id)
);

CREATE INDEX IF NOT EXISTS idx_{{.Spec.Table}}_tenant ON {{.Spec.Table}} (tenant_id, id DESC)
  WHERE deleted_at IS NULL;

DROP TRIGGER IF EXISTS trg_fill_tenant_id ON {{.Spec.Table}};
CREATE TRIGGER trg_fill_tenant_id
  BEFORE INSERT ON {{.Spec.Table}}
  FOR EACH ROW EXECUTE FUNCTION app_fill_tenant_id();

ALTER TABLE {{.Spec.Table}} ENABLE ROW LEVEL SECURITY;
ALTER TABLE {{.Spec.Table}} FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_isolation ON {{.Spec.Table}};
CREATE POLICY tenant_isolation ON {{.Spec.Table}}
  USING (app_rls_bypass() OR tenant_id = app_current_tenant_id())
  WITH CHECK (app_rls_bypass() OR tenant_id = app_current_tenant_id());
`

